import 'dart:io';import 'dart:convert';import 'package:flutter/material.dart';import 'package:provider/provider.dart';import 'package:file_picker/file_picker.dart';import 'package:path_provider/path_provider.dart';import 'package:share_plus/share_plus.dart';import '../../services/preferences_service.dart';import '../../providers/task_store.dart';import '../../repositories/task_repository.dart';import '../../services/notification_service.dart';
class SettingsScreen extends StatelessWidget{const SettingsScreen({super.key});@override Widget build(BuildContext context){final p=context.watch<PreferencesService>();final s=context.watch<TaskStore>();return Scaffold(appBar:AppBar(title:const Text('الإعدادات',style:TextStyle(fontWeight:FontWeight.bold))),body:ListView(padding:const EdgeInsets.all(16),children:[_section(context,'المظهر واللغة'),Card(child:Column(children:[ListTile(leading:const Icon(Icons.palette_outlined),title:const Text('المظهر'),subtitle:Text(p.themeMode==ThemeMode.system?'حسب النظام':p.themeMode==ThemeMode.dark?'داكن':'فاتح'),trailing:DropdownButton<ThemeMode>(value:p.themeMode,underline:const SizedBox(),items:const [DropdownMenuItem(value:ThemeMode.system,child:Text('تلقائي')),DropdownMenuItem(value:ThemeMode.light,child:Text('فاتح')),DropdownMenuItem(value:ThemeMode.dark,child:Text('داكن'))],onChanged:(v){if(v!=null)p.setTheme(v);})),ListTile(leading:const Icon(Icons.language),title:const Text('لغة التطبيق'),trailing:DropdownButton<String>(value:p.locale.languageCode,underline:const SizedBox(),items:const [DropdownMenuItem(value:'ar',child:Text('العربية')),DropdownMenuItem(value:'en',child:Text('English'))],onChanged:(v){if(v!=null)p.setLocale(v);})),ListTile(leading:const Icon(Icons.calendar_month),title:const Text('بداية الأسبوع'),trailing:DropdownButton<int>(value:p.weekStart,underline:const SizedBox(),items:const [DropdownMenuItem(value:6,child:Text('السبت')),DropdownMenuItem(value:0,child:Text('الأحد')),DropdownMenuItem(value:1,child:Text('الإثنين'))],onChanged:(v){if(v!=null)p.setWeekStart(v);}))])),_section(context,'التذكيرات'),Card(child:SwitchListTile(secondary:const Icon(Icons.notifications_active_outlined),title:const Text('التذكيرات المحلية'),subtitle:const Text('تعمل دون إنترنت، وقد تكون غير دقيقة التوقيت على بعض الأجهزة'),value:p.notificationsEnabled,onChanged:(v)async{await p.setNotifications(v);if(!v)await NotificationService.instance.cancelAll();else await NotificationService.instance.requestPermission();})),_section(context,'البيانات'),Card(child:Column(children:[ListTile(leading:const Icon(Icons.file_upload_outlined),title:const Text('تصدير المهام'),subtitle:const Text('حفظ نسخة JSON لمشاركتها أو الاحتفاظ بها'),onTap:()=>_export(context)),ListTile(leading:const Icon(Icons.file_download_outlined),title:const Text('استيراد ملف JSON'),onTap:()=>_import(context,s)),ListTile(leading:Icon(Icons.delete_forever_outlined,color:Theme.of(context).colorScheme.error),title:const Text('مسح جميع البيانات'),subtitle:const Text('لا يمكن التراجع عن هذا الإجراء'),onTap:()=>_clear(context,s))])),_section(context,'حول التطبيق'),const Card(child:Column(children:[ListTile(leading:Icon(Icons.task_alt_rounded),title:Text('TaskFlow'),subtitle:Text('مدير مهام محلي يعمل دون إنترنت')),ListTile(leading:Icon(Icons.info_outline),title:Text('الإصدار'),trailing:Text('1.0.0')),ListTile(leading:Icon(Icons.lock_outline),title:Text('خصوصيتك أولًا'),subtitle:Text('لا يتطلب حسابًا ولا يرسل بياناتك إلى خادم.'))]))]));}
 Widget _section(BuildContext c,String title)=>Padding(padding:const EdgeInsets.fromLTRB(4,22,4,8),child:Text(title,style:Theme.of(c).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.bold)));
 Future<void> _export(BuildContext c)async{try{final data=await TaskRepository().exportJson();final dir=await getTemporaryDirectory();final file=File('${dir.path}/TaskFlow-backup-${DateTime.now().millisecondsSinceEpoch}.json');await file.writeAsString(data);await Share.shareXFiles([XFile(file.path)],text:'نسخة احتياطية من TaskFlow');}catch(e){if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('تعذر التصدير: $e')));}}
 Future<void> _import(BuildContext c,TaskStore s)async{try{final result=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['json'],withData:true);if(result==null)return;final bytes=result.files.single.bytes;if(bytes==null)throw const FormatException('تعذر قراءة الملف');final n=await TaskRepository().importJson(utf8.decode(bytes));await s.load();if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('تم استيراد $n مهمة.')));}catch(e){if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('لم يتم الاستيراد: $e')));}}
 Future<void> _clear(BuildContext c,TaskStore s)async{final ok=await showDialog<bool>(context:c,builder:(d)=>AlertDialog(title:const Text('مسح كل البيانات؟'),content:const Text('سيتم حذف جميع المهام والفئات المخصصة والتذكيرات.'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('مسح الكل'))]));if(ok==true){await s.repository.clear();await NotificationService.instance.cancelAll();await s.load();if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('تم مسح البيانات.')));}}
}
